package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

type PartRec struct {
	LbPart   string
	LbRegion string
	LbSerial int64
}

var WsEofFlag string = "N"
var WsLabel string
var WsACount int64 = 0
var WsTotalA int64 = 0
var WsCount int64 = 0

var curRec PartRec
var inputLines []string
var inputPos int

func init() {
	WsLabel = strings.Repeat(" ", 20)
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func delimitedBySpace(s string) string {
	if idx := strings.Index(s, " "); idx >= 0 {
		return s[:idx]
	}
	return s
}

func formatPIC(val int64, digits int) string {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if val < 0 {
		val = ((val % mod) + mod) % mod
	} else {
		val = val % mod
	}
	return fmt.Sprintf("%0*d", digits, val)
}

func parseSerial(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	v, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		filtered := ""
		for _, ch := range t {
			if (ch >= '0' && ch <= '9') || ch == '-' || ch == '+' {
				filtered += string(ch)
			}
		}
		if filtered == "" || filtered == "-" || filtered == "+" {
			return 0
		}
		v2, err2 := strconv.ParseInt(filtered, 10, 64)
		if err2 != nil {
			return 0
		}
		v = v2
	}
	mod := int64(10000)
	if v < 0 {
		v = ((v % mod) + mod) % mod
	} else {
		v = v % mod
	}
	return v
}

func openPartFile() error {
	WsEofFlag = "N"
	// reset working storage as initial state (not strictly required)
	// WsLabel already spaces, counts zero
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			inputLines = []string{}
			inputPos = 0
			return nil
		}
		return err
	}
	if len(data) == 0 {
		inputLines = []string{}
		inputPos = 0
		return nil
	}
	text := string(data)
	text = strings.ReplaceAll(text, "\r\n", "\n")
	parts := strings.Split(text, "\n")
	endsWithNewline := strings.HasSuffix(text, "\n")
	if endsWithNewline {
		if len(parts) > 0 && parts[len(parts)-1] == "" {
			parts = parts[:len(parts)-1]
		}
	}
	inputLines = parts
	inputPos = 0
	return nil
}

func closePartFile() {
}

func ReadPara() {
	if inputPos >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputPos]
	inputPos++
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	curRec.LbPart = line[0:8]
	curRec.LbRegion = line[8:11]
	serialStr := line[11:15]
	curRec.LbSerial = parseSerial(serialStr)
}

func ProcessPara() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	// INSPECT LB-PART TALLYING FOR ALL "A"
	WsACount = int64(strings.Count(curRec.LbPart, "A"))
	WsACount = WsACount % 100

	regionPart := delimitedBySpace(curRec.LbRegion)
	partPart := delimitedBySpace(curRec.LbPart)
	serialFormatted := formatPIC(curRec.LbSerial, 4)

	concat := regionPart + "-" + partPart + "-" + serialFormatted
	if len(concat) > 20 {
		concat = concat[:20]
	}
	WsLabel = concat + strings.Repeat(" ", 20-len(concat))
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	WsTotalA = WsTotalA + WsACount
	WsTotalA = WsTotalA % 1000
	WsCount = WsCount + 1
	WsCount = WsCount % 1000

	fmt.Printf("%s A=%s\n", WsLabel, formatPIC(WsACount, 2))
	ReadPara()
}

func SummaryPara() {
	fmt.Printf("LABELS: %s A-TOTAL: %s\n", formatPIC(WsCount, 3), formatPIC(WsTotalA, 3))
}

func MainPara() {
	if err := openPartFile(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	closePartFile()
	SummaryPara()
}

func main() {
	MainPara()
}
